import logging
import logging.handlers
import os

LOG_FILE = True
LOG_DIR = '/home/ute/btsauto/logs'
LOG_FILE_NAME = 'elementmanager2g_debug.log'
LOG_SIZE = 5000000
LOG_NB = 3
formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")

console_handler = logging.StreamHandler()
console_handler.setFormatter(formatter)
console_handler.setLevel(logging.DEBUG)

logger = logging.Logger('framework')
logger.addHandler(console_handler)
logger.setLevel(logging.DEBUG)
if LOG_FILE and os.path.exists('{}'.format(LOG_DIR)):
    LOG_PATH = '{}/{}'.format(LOG_DIR, LOG_FILE_NAME)
    log_file_handler = logging.handlers.RotatingFileHandler(LOG_PATH, maxBytes=LOG_SIZE, backupCount=LOG_NB)
    log_file_handler.setFormatter(formatter)
    log_file_handler.setLevel(logging.DEBUG)
    logger.addHandler(log_file_handler)
